with matched_keys as (select country, id from customers intersect all select country, id from customers where city not in ('Berlin', 'Bangkok', 'Singapore')), reconciled as (select s.* from customers s inner join matched_keys k on s.country = k.country and s.id = k.id) select case when age >= 63 then 'HIGH' else 'LOW' end as age_tier, date_trunc('week', signup_date) as week_start, count(*) as num_rows, sum(credit_limit) filter (where country = 'TH') as th_total_credit_limit, avg(credit_limit) filter (where segment = 'Consumer') as consumer_avg_credit_limit, count(*) as row_count, count(*) as cnt, approx_percentile(credit_limit, 0.9) as credit_limit_p90 from reconciled group by case when age >= 63 then 'HIGH' else 'LOW' end, date_trunc('week', signup_date) order by num_rows nulls first;
